import assert from 'node:assert/strict';
import { executeWorkflow } from './src/engine.js';

const date = new Date('2026-03-14T08:30:00.000Z');

const workflow = {
  id: 'repro',
  entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'form-one' },
    { id: 'form-one', type: 'form', next: 'form-two', schema: { fields: [
      { path: 'date.label', type: 'string', default: '已安排' },
    ] } },
    { id: 'form-two', type: 'form', next: 'after', schema: { fields: [
      { path: 'date.note', type: 'string', default: '临时备注' },
      { path: 'draft.detail', type: 'string', default: 'x' },
      { path: 'approval', type: 'string', required: true },
    ] } },
    { id: 'after', type: 'end', result: 'done' },
  ],
};

const result = executeWorkflow(workflow, { date });
console.log('status:', result.status);
console.log('date is Date?', result.context.input.date instanceof Date);
console.log('date time:', result.context.input.date?.getTime?.());
console.log('date own props:', result.context.input.date ? Object.getOwnPropertyNames(result.context.input.date) : 'n/a');
console.log('label:', result.context.input.date?.label);
console.log('draft present?', Object.hasOwn(result.context.input, 'draft'));
assert.equal(result.status, 'invalid_input');
assert.ok(result.context.input.date instanceof Date, 'date must stay a Date');
assert.equal(result.context.input.date.getTime(), date.getTime());
assert.equal(result.context.input.date.label, '已安排');
assert.equal(Object.hasOwn(result.context.input.date, 'note'), false);
assert.equal(Object.hasOwn(result.context.input, 'draft'), false);
console.log('ALL GOOD');

