// Snapshot of the run input taken the instant a form starts processing, used
// to undo that form's own writes when validation fails. A plain
// structuredClone is not enough: a successful earlier form may have attached
// a default as an own property of a value structuredClone copies only by
// internal slot — a Date most notably, but also RegExp, Map/Set, buffers and
// views, boxed primitives and Errors. structuredClone discards every such
// attached property, so restoring a per-form structuredClone would delete the
// earlier form's successful defaults together with the failed form's writes.
// The working input is itself the entry-time structured clone (and forms only
// ever add plain parent objects and primitive defaults), so every value here
// is structured-cloneable and carries no shared memory; this clone walks that
// graph itself, recreating each structured-clone kind while (a) copying the
// own enumerable properties structuredClone would drop from internal-slot
// values and (b) keeping repeated and circular references intact through a
// source->clone identity map. The result is independent of the working input
// at every level.
function cloneFormInputState(input) {
  const clones = new Map();

  const cloneValue = value => {
    if (value === null || typeof value !== 'object') return value;
    const existing = clones.get(value);
    if (existing !== undefined) return existing;

    // Internal-slot container: recreate with the same entries/members, then
    // attach the own enumerable properties (the expando defaults forms add).
    if (nodeTypes.isMap(value)) {
      const copy = new Map();
      clones.set(value, copy);
      for (const [key, member] of value) copy.set(cloneValue(key), cloneValue(member));
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }
    if (nodeTypes.isSet(value)) {
      const copy = new Set();
      clones.set(value, copy);
      for (const member of value) copy.add(cloneValue(member));
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }

    if (nodeTypes.isDate(value)) {
      const copy = new Date(value.getTime());
      clones.set(value, copy);
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }
    if (nodeTypes.isRegExp(value)) {
      const copy = new RegExp(value.source, value.flags);
      clones.set(value, copy);
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }

    if (nodeTypes.isArrayBuffer(value)) {
      const copy = value.slice(0);
      clones.set(value, copy);
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }
    if (nodeTypes.isTypedArray(value)) {
      // The constructor produces a fresh buffer of the same element type and
      // length; iterating copies each element (a zero-fill would mis-handle
      // BigInt views and detached/ragged cases the constructor would reject).
      const copy = new value.constructor(value);
      clones.set(value, copy);
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }
    if (nodeTypes.isDataView(value)) {
      const copy = new DataView(value.buffer.slice(0), value.byteOffset, value.byteLength);
      clones.set(value, copy);
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }

    // Errors clone as the same built-in class; own properties other than
    // "cause" are dropped, matching structuredClone. A subclass keeps a plain
    // Error of its constructor name only when it is one of the built-ins.
    const errorBuiltin = builtinErrorConstructor(value);
    if (errorBuiltin !== null) {
      const copy = new errorBuiltin(value.message);
      if ('cause' in value) {
        Object.defineProperty(copy, 'cause', {
          value: cloneValue(value.cause), writable: true, enumerable: false, configurable: true,
        });
      }
      clones.set(value, copy);
      return copy;
    }

    if (nodeTypes.isBoxedPrimitive(value)) {
      // Preserve the wrapper type and its wrapped primitive.
      let copy;
      if (nodeTypes.isNumberObject(value)) copy = new Number(value.valueOf());
      else if (nodeTypes.isStringObject(value)) copy = new String(value.valueOf());
      else if (nodeTypes.isBooleanObject(value)) copy = new Boolean(value.valueOf());
      else if (nodeTypes.isBigIntObject(value)) copy = Object(value.valueOf());
      else copy = Object(value.valueOf()); // Symbol boxed object
      clones.set(value, copy);
      copyEnumerableOwnProps(value, copy, cloneValue);
      return copy;
    }

    if (Array.isArray(value)) {
      const copy = [];
      clones.set(value, copy);
      for (const key of Object.keys(value)) {
        const index = Number(key);
        if (Number.isInteger(index) && String(index) === key && index >= 0) {
          copy[index] = cloneValue(value[key]);
        } else {
          copy[key] = cloneValue(value[key]);
        }
      }
      copy.length = value.length;
      return copy;
    }

    // Plain objects and arbitrary class instances without a structured-clone
    // internal slot clone as plain objects carrying their own enumerable
    // string-keyed properties, exactly as structuredClone treats them.
    const copy = {};
    clones.set(value, copy);
    copyEnumerableOwnProps(value, copy, cloneValue);
    return copy;
  };

  return cloneValue(input);
}

// Copies the source's own enumerable string-keyed properties onto the target,
// recursively cloning each value. This is the property set structuredClone
// copies for ordinary objects — and that it silently drops from internal-slot
// values such as Date, where form defaults nevertheless land.
function copyEnumerableOwnProps(source, target, cloneValue) {
  for (const key of Object.keys(source)) {
    target[key] = cloneValue(source[key]);
  }
}

// Maps an Error to its built-in constructor so the snapshot recreates the same
// class; returns null for values that are not a recognized native Error.
function builtinErrorConstructor(value) {
  if (!nodeTypes.isNativeError(value)) return null;
  const name = value.constructor && value.constructor.name;
  if (name === 'EvalError') return EvalError;
  if (name === 'RangeError') return RangeError;
  if (name === 'ReferenceError') return ReferenceError;
  if (name === 'SyntaxError') return SyntaxError;
  if (name === 'TypeError') return TypeError;
  if (name === 'URIError') return URIError;
  if (name === 'Error') return Error;
  return Error;
}

function processForm(node, input, compiled) {
  const snapshot = cloneFormInputState(input);
  const errors = [];
  for (const spec of compiled) {
    const fieldError = processFormField(spec, input, node.id);
    if (fieldError) errors.push(fieldError);
  }
  return errors.length === 0
    ? { ok: true }
    : { ok: false, errors, rollback: snapshot };
}

