import assert from 'node:assert/strict';
import { executeWorkflow, executeWorkflowAsync } from './src/engine.js';

const baseDate = new Date('2026-03-14T08:30:00.000Z');

// Rich input exercising every structured-clone kind. Expandos are added by a
// successful form-one; form-two then adds more expandos and fails.
function richInput() {
  return {
    date: new Date(baseDate.getTime()),
    re: /ok/gi,
    map: new Map([['k', 1]]),
    set: new Set(['a']),
    buf: new ArrayBuffer(4),
    bytes: new Uint8Array([7, 8, 9]),
    view: new DataView(new ArrayBuffer(8)),
    num: new Number(5),
    list: [1, { x: 2 }],
    plain: { keep: 'yes' },
  };
}

function workflow(extraFormTwoFields) {
  return {
    id: 'rich',
    entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'f1' },
      { id: 'f1', type: 'form', next: 'f2', schema: { fields: [
        { path: 'date.tag', type: 'string', default: 'D' },
        { path: 're.tag', type: 'string', default: 'R' },
        { path: 'map.tag', type: 'string', default: 'M' },
        { path: 'set.tag', type: 'string', default: 'S' },
        { path: 'buf.tag', type: 'string', default: 'B' },
        { path: 'bytes.tag', type: 'string', default: 'U' },
        { path: 'view.tag', type: 'string', default: 'V' },
        { path: 'num.tag', type: 'string', default: 'N' },
      ] } },
      { id: 'f2', type: 'form', next: 'done', schema: { fields: [
        ...extraFormTwoFields,
        { path: 'approval', type: 'string', required: true },
      ] } },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
}

const tempFields = [
  { path: 'date.temp', type: 'string', default: 'dT' },
  { path: 're.temp', type: 'string', default: 'rT' },
  { path: 'map.temp', type: 'string', default: 'mT' },
  { path: 'set.temp', type: 'string', default: 'sT' },
  { path: 'buf.temp', type: 'string', default: 'bT' },
  { path: 'bytes.temp', type: 'string', default: 'uT' },
  { path: 'view.temp', type: 'string', default: 'vT' },
  { path: 'num.temp', type: 'string', default: 'nT' },
  { path: 'brand.new.deep', type: 'string', default: 'z' },
];

function assertRichRestored(input) {
  assert.ok(input.date instanceof Date);
  assert.equal(input.date.getTime(), baseDate.getTime());
  assert.equal(input.date.tag, 'D');
  assert.equal(Object.hasOwn(input.date, 'temp'), false);

  assert.ok(input.re instanceof RegExp);
  assert.equal(input.re.source, 'ok');
  assert.equal(input.re.flags, 'gi');
  assert.equal(input.re.tag, 'R');
  assert.equal(Object.hasOwn(input.re, 'temp'), false);

  assert.ok(input.map instanceof Map);
  assert.deepEqual([...input.map], [['k', 1]]);
  assert.equal(input.map.tag, 'M');
  assert.equal(Object.hasOwn(input.map, 'temp'), false);

  assert.ok(input.set instanceof Set);
  assert.deepEqual([...input.set], ['a']);
  assert.equal(input.set.tag, 'S');
  assert.equal(Object.hasOwn(input.set, 'temp'), false);

  assert.ok(input.buf instanceof ArrayBuffer);
  assert.equal(input.buf.byteLength, 4);
  assert.equal(input.buf.tag, 'B');
  assert.equal(Object.hasOwn(input.buf, 'temp'), false);

  assert.ok(input.bytes instanceof Uint8Array);
  assert.deepEqual([...input.bytes], [7, 8, 9]);
  assert.equal(input.bytes.tag, 'U');
  assert.equal(Object.hasOwn(input.bytes, 'temp'), false);

  assert.ok(input.view instanceof DataView);
  assert.equal(input.view.byteLength, 8);
  assert.equal(input.view.tag, 'V');
  assert.equal(Object.hasOwn(input.view, 'temp'), false);

  assert.equal(typeof input.num, 'object');
  assert.equal(input.num.valueOf(), 5);
  assert.equal(input.num.tag, 'N');
  assert.equal(Object.hasOwn(input.num, 'temp'), false);

  assert.deepEqual(input.list, [1, { x: 2 }]);
  assert.deepEqual(input.plain, { keep: 'yes' });
  assert.equal(Object.hasOwn(input, 'brand'), false);
  assert.equal(Object.hasOwn(input, 'approval'), false);
}

for (const [name, run] of [
  ['sync', (wf, input) => executeWorkflow(wf, input)],
  ['async', (wf, input) => executeWorkflowAsync(wf, input)],
]) {
  const input = richInput();
  const snapshot = structuredClone(input);
  const result = await run(workflow(tempFields), input);
  assert.equal(result.status, 'invalid_input', name);
  assert.deepEqual(result.errors, [{ nodeId: 'f2', path: 'approval', code: 'required' }], name);
  assertRichRestored(result.context.input);
  // Caller untouched, and its leaves never gained expandos.
  assert.deepEqual(input, snapshot);
  assert.equal(Object.hasOwn(input.date, 'tag'), false, name);
  assert.equal(Object.hasOwn(input.bytes, 'tag'), false, name);
  // Run input is an independent copy.
  assert.notEqual(result.context.input.date, input.date, name);
  assert.notEqual(result.context.input.bytes, input.bytes, name);
  console.log(name, 'rich leaf rollback OK');
}

// Two input fields alias the same Date; both views must agree post-rollback.
{
  const shared = new Date(baseDate.getTime());
  const wf = {
    id: 'alias-date',
    entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'f1' },
      { id: 'f1', type: 'form', next: 'f2', schema: { fields: [
        { path: 'd1.label', type: 'string', default: '已安排' },
      ] } },
      { id: 'f2', type: 'form', next: 'done', schema: { fields: [
        { path: 'd2.note', type: 'string', default: '临时备注' },
        { path: 'draft.detail', type: 'string', default: 'x' },
        { path: 'approval', type: 'string', required: true },
      ] } },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  const input = { d1: shared, d2: shared };
  const result = executeWorkflow(wf, input);
  assert.equal(result.status, 'invalid_input');
  const { d1, d2 } = result.context.input;
  assert.ok(d1 instanceof Date && d2 instanceof Date);
  assert.equal(d1, d2, 'aliases still point at the same restored Date');
  assert.equal(d1.getTime(), baseDate.getTime());
  assert.equal(d1.label, '已安排');
  assert.equal(d2.label, '已安排');
  assert.equal(Object.hasOwn(d1, 'note'), false);
  assert.equal(Object.hasOwn(d2, 'note'), false);
  assert.equal(Object.hasOwn(result.context.input, 'draft'), false);
  assert.notEqual(d1, shared, 'restored Date is independent of caller');
  assert.equal(input.d1, input.d2, 'caller aliases intact');
  console.log('shared-Date alias rollback OK');
}

// Success control: defaults on a Date stay and are readable by a later condition.
{
  const wf = {
    id: 'success',
    entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'f1' },
      { id: 'f1', type: 'form', next: 'check', schema: { fields: [
        { path: 'date.label', type: 'string', default: '已安排' },
      ] } },
      { id: 'check', type: 'condition', then: 'seen', else: 'missed',
        condition: { field: 'date.label', operator: 'eq', value: '已安排' } },
      { id: 'seen', type: 'end', result: 'visible' },
      { id: 'missed', type: 'end', result: 'missing' },
    ],
  };
  const result = await executeWorkflowAsync(wf, { date: new Date(baseDate.getTime()) });
  assert.equal(result.status, 'completed');
  assert.equal(result.result, 'visible');
  assert.ok(result.context.input.date instanceof Date);
  assert.equal(result.context.input.date.getTime(), baseDate.getTime());
  assert.equal(result.context.input.date.label, '已安排');
  console.log('success keeps Date defaults readable OK');
}

console.log('ALL EDGE CASES PASS');

