node --input-type=module -e '
import assert from "node:assert/strict";
import { executeWorkflow, executeWorkflowAsync } from "./src/engine.js";

// Exact scenario from the task description.
function runWith(entry) {
  const wf = {
    id: "desc", entry: "start",
    nodes: [
      { id: "start", type: "trigger", next: "form-one" },
      { id: "form-one", type: "form", next: "form-two", schema: { fields: [
        { path: "date.label", type: "string", default: "已安排" },
      ] } },
      { id: "form-two", type: "form", next: "after", schema: { fields: [
        { path: "date.note", type: "string", default: "临时备注" },
        { path: "draft.detail", type: "string", default: "x" },
        { path: "approval", type: "string", required: true },
      ] } },
      { id: "after", type: "end", result: "done" },
    ],
  };
  return entry === "sync"
    ? executeWorkflow(wf, { date: new Date(1773477000000) })
    : executeWorkflowAsync(wf, { date: new Date(1773477000000) });
}
for (const mode of ["sync", "async"]) {
  const r = await runWith(mode);
  assert.equal(r.status, "invalid_input", mode);
  assert.ok(r.context.input.date instanceof Date, mode);
  assert.equal(r.context.input.date.getTime(), 1773477000000, mode);
  assert.equal(r.context.input.date.label, "已安排", mode);
  assert.equal(Object.hasOwn(r.context.input.date, "note"), false, mode);
  assert.equal(Object.hasOwn(r.context.input, "draft"), false, mode);
  assert.deepEqual(r.errors, [{ nodeId: "form-two", path: "approval", code: "required" }], mode);
  assert.deepEqual(r.trace.map(t => t.nodeId), ["start","form-one","form-two"], mode);
  console.log(mode, "matches task description exactly");
}
'
